<?php session_start();require 'admin_db.php';$uid=$_SESSION['userID']??'';if(!$uid)die('Please login as student.');$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$gid=trim($_POST['groupID']);$sub=trim($_POST['targeted_subjects']);$type=trim($_POST['type']);$faculty=trim($_POST['faculty']);$s=mysqli_prepare($conn,'SELECT groupID FROM group_info WHERE groupID=?');mysqli_stmt_bind_param($s,'s',$gid);mysqli_stmt_execute($s);if(mysqli_fetch_assoc(mysqli_stmt_get_result($s)))$msg='Group ID already exists.';else{$s=mysqli_prepare($conn,'SELECT userID FROM user_info WHERE userID=?');mysqli_stmt_bind_param($s,'s',$uid);mysqli_stmt_execute($s);$u=mysqli_fetch_assoc(mysqli_stmt_get_result($s));$aid='';if($u)$aid=$u['AdminID'];$s=mysqli_prepare($conn,'INSERT INTO group_info(groupID,group_creator_uid,type,targeted_subjects,adminID) VALUES(?,?,?,?,?)');mysqli_stmt_bind_param($s,'sssss',$gid,$uid,$type,$sub,$aid);if(mysqli_stmt_execute($s)){mysqli_query($conn,"INSERT INTO student_joins_group(groupID,student_UID,joindate,leaveDate) VALUES('".mysqli_real_escape_string($conn,$gid)."','".mysqli_real_escape_string($conn,$uid)."',CURDATE(),NULL)");if($faculty!==''){ $s=mysqli_prepare($conn,'INSERT INTO group_consult_faculty(groupID,faculty_uID) VALUES(?,?)');mysqli_stmt_bind_param($s,'ss',$gid,$faculty);mysqli_stmt_execute($s);} $msg='Group formation request submitted; connected admin must approve.';}}}$fac=mysqli_query($conn,'SELECT f.userID,f.Initial FROM faculty_info f ORDER BY f.userID');?>
<!doctype html><html><head><title>Form Group</title><link rel="stylesheet" href="admin_pages.css"></head><body><div class="page"><div class="panel"><h1>Form Study Group</h1><?php if($msg)echo'<div class="notice">'.htmlspecialchars($msg).'</div>';?><form method="post"><label>Unique Group ID</label><input name="groupID" required><label>Type</label><input name="type" placeholder="Public / Private" required><label>Targeted Subject</label><input name="targeted_subjects" required><label>Take Faculty Consultation (optional)</label><select name="faculty"><option value="">No faculty selected</option><?php while($f=mysqli_fetch_assoc($fac)):?><option value="<?=$f['userID']?>"><?=$f['userID']?> - <?=htmlspecialchars($f['Initial'])?></option><?php endwhile;?></select><button>Submit Group Formation Request</button></form></div></div></body></html>
